UPDATE inventory
SET stock = stock - 2, updated_at = NOW()
WHERE product_id = 501 AND stock >= 2;
SELECT ROW_COUNT() AS affected_rows;

START TRANSACTION;
UPDATE inventory SET stock = stock - 1, updated_at = NOW()
WHERE product_id = 501 AND stock >= 1;
SET @affected = ROW_COUNT();
INSERT INTO order_items (order_id, product_id, unit_price, quantity)
VALUES (9001, 501, 199.00, 1);
COMMIT;
SELECT @affected AS affected_rows;

UPDATE inventory
SET stock = stock - 1, version = version + 1
WHERE product_id = 501 AND version = 12 AND stock >= 1;
